def isSolvable(words, result):
    all_words = words + [result]
    letters = set(''.join(all_words))
    if len(letters) > 10:
        return False

    # weight[c] = signed place-value contribution of c to (sum(words) - result)
    weight = {c: 0 for c in letters}
    for w in words:
        p = 1
        for c in reversed(w):
            weight[c] += p
            p *= 10
    p = 1
    for c in reversed(result):
        weight[c] -= p
        p *= 10

    # Letters that cannot be 0 (leading letter of a multi-digit word)
    nonzero = {w[0] for w in all_words if len(w) > 1}

    # Order letters column by column (least significant first)
    order, seen, checkpoints = [], set(), {}
    m = max(map(len, all_words))
    for col in range(m):
        for w in all_words:
            if col < len(w) and w[-1 - col] not in seen:
                seen.add(w[-1 - col])
                order.append(w[-1 - col])
        # Once columns 0..col are fully assigned, total must be divisible by 10^(col+1)
        checkpoints[len(order)] = 10 ** (col + 1)

    def dfs(k, used, total):
        if k in checkpoints and total % checkpoints[k] != 0:
            return False
        if k == len(order):
            return total == 0
        c = order[k]
        for d in range(10):
            if (used >> d) & 1 or (d == 0 and c in nonzero):
                continue
            if dfs(k + 1, used | (1 << d), total + weight[c] * d):
                return True
        return False

    return dfs(0, 0, 0)
